BEGIN;
-- Additive migration. Preserve old conversations in human mode.
ALTER TABLE "ChatSession" ADD COLUMN "mode" TEXT NOT NULL DEFAULT 'BOT', ADD COLUMN "assignedAdminId" TEXT, ADD COLUMN "pendingMessageId" TEXT, ADD COLUMN "pendingSince" TIMESTAMP(3), ADD COLUMN "clarificationCount" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "handoffCycle" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "messageSequence" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "resolvedAt" TIMESTAMP(3);
UPDATE "ChatSession" SET "mode"=CASE WHEN "status"='CLOSED' THEN 'RESOLVED' ELSE 'WAITING_HUMAN' END;
ALTER TABLE "ChatMessage" ADD COLUMN "sequence" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "clientMessageId" TEXT, ADD COLUMN "inReplyToId" TEXT, ADD COLUMN "sources" JSONB;
WITH ordered AS (SELECT "id", ROW_NUMBER() OVER (PARTITION BY "chatSessionId" ORDER BY "createdAt", "id") AS n FROM "ChatMessage") UPDATE "ChatMessage" m SET "sequence"=ordered.n FROM ordered WHERE m."id"=ordered."id";
UPDATE "ChatSession" s SET "messageSequence"=(SELECT COALESCE(MAX(m."sequence"),0) FROM "ChatMessage" m WHERE m."chatSessionId"=s."id");
DROP INDEX IF EXISTS "ChatMessage_chatSessionId_idx";
CREATE INDEX "ChatMessage_chatSessionId_sequence_idx" ON "ChatMessage"("chatSessionId","sequence");
CREATE UNIQUE INDEX "ChatMessage_inReplyToId_key" ON "ChatMessage"("inReplyToId");
CREATE UNIQUE INDEX "ChatMessage_chatSessionId_clientMessageId_key" ON "ChatMessage"("chatSessionId","clientMessageId");
CREATE TABLE "SupportArticle" ("id" TEXT NOT NULL, "question" TEXT NOT NULL, "answer" TEXT NOT NULL, "category" TEXT NOT NULL, "aliases" JSONB NOT NULL DEFAULT '[]', "audience" TEXT NOT NULL DEFAULT 'ACCOUNT', "status" TEXT NOT NULL DEFAULT 'DRAFT', "isStarter" BOOLEAN NOT NULL DEFAULT false, "sortOrder" INTEGER NOT NULL DEFAULT 0, "version" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SupportArticle_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SupportArticle_status_audience_sortOrder_idx" ON "SupportArticle"("status","audience","sortOrder");
CREATE TABLE "SupportSettings" ("id" TEXT NOT NULL DEFAULT 'main', "version" INTEGER NOT NULL DEFAULT 1, "enabled" BOOLEAN NOT NULL DEFAULT true, "aiEnabled" BOOLEAN NOT NULL DEFAULT false, "publicAiEnabled" BOOLEAN NOT NULL DEFAULT false, "geminiModel" TEXT NOT NULL DEFAULT '', "encryptedApiKey" TEXT, "dailyLimit" INTEGER NOT NULL DEFAULT 100, "usageDate" TEXT NOT NULL DEFAULT '', "dailyCalls" INTEGER NOT NULL DEFAULT 0, "welcomeMessage" TEXT NOT NULL DEFAULT 'Hola, soy el asistente de NexoPOS. Elige un tema o escribe tu consulta. Puedes pedir hablar con una persona en cualquier momento.', "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SupportSettings_pkey" PRIMARY KEY ("id"));
INSERT INTO "SupportSettings"("id","updatedAt") VALUES ('main',CURRENT_TIMESTAMP);
CREATE TABLE "SupportHandoffNotice" ("id" TEXT NOT NULL, "chatSessionId" TEXT NOT NULL, "cycle" INTEGER NOT NULL, "title" TEXT NOT NULL, "message" TEXT NOT NULL, "notificationId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "attempts" INTEGER NOT NULL DEFAULT 0, "nextAttemptAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "leaseUntil" TIMESTAMP(3), "leaseToken" TEXT, "providerId" TEXT, "lastError" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SupportHandoffNotice_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SupportHandoffNotice_chatSessionId_cycle_key" ON "SupportHandoffNotice"("chatSessionId","cycle");
CREATE INDEX "SupportHandoffNotice_status_nextAttemptAt_idx" ON "SupportHandoffNotice"("status","nextAttemptAt");
ALTER TABLE "SupportHandoffNotice" ADD CONSTRAINT "SupportHandoffNotice_chatSessionId_fkey" FOREIGN KEY ("chatSessionId") REFERENCES "ChatSession"("id") ON DELETE CASCADE ON UPDATE CASCADE;
INSERT INTO "SupportArticle"("id","question","answer","category","audience","isStarter","aliases","status","sortOrder","updatedAt") VALUES ('36aa8e0a-448e-4aac-9d33-000000000001','¿Cómo creo las categorías de mis productos?','Las categorías agrupan tus productos en familias para mantener el catálogo ordenado. En Categorías, crea los grupos que usas en tu negocio; por ejemplo, un chocolate puede pertenecer a Confites. Luego asigna la categoría correspondiente al ingresar cada producto.','Primeros pasos','ACCOUNT',true,'["crear categorias","categorías de productos"]','PUBLISHED',0,CURRENT_TIMESTAMP);
INSERT INTO "SupportArticle"("id","question","answer","category","audience","isStarter","aliases","status","sortOrder","updatedAt") VALUES ('36aa8e0a-448e-4aac-9d33-000000000002','¿Cómo ingreso las marcas de mis productos?','En Marcas, registra las marcas comerciales de los productos que vendes. Después podrás asociar cada producto a su marca al completar su ficha en Productos.','Primeros pasos','ACCOUNT',true,'["crear marcas","ingresar marcas"]','PUBLISHED',1,CURRENT_TIMESTAMP);
INSERT INTO "SupportArticle"("id","question","answer","category","audience","isStarter","aliases","status","sortOrder","updatedAt") VALUES ('36aa8e0a-448e-4aac-9d33-000000000003','¿Cómo ingreso un producto?','Primero registra sus categorías y marcas. Luego entra a Productos, crea el producto y completa todos los campos requeridos. Asigna su categoría y marca, y agrega una imagen principal que permita identificarlo con claridad. Revisa la información antes de guardar.','Primeros pasos','ACCOUNT',true,'["agregar producto","crear producto"]','PUBLISHED',2,CURRENT_TIMESTAMP);
INSERT INTO "SupportArticle"("id","question","answer","category","audience","isStarter","aliases","status","sortOrder","updatedAt") VALUES ('36aa8e0a-448e-4aac-9d33-000000000004','¿Cómo registro mis proveedores?','En Proveedores, agrega las empresas o personas que abastecen tu negocio. Completa los datos requeridos y revisa sus datos de contacto antes de guardar.','Primeros pasos','ACCOUNT',true,'["crear proveedor","ingresar proveedores"]','PUBLISHED',3,CURRENT_TIMESTAMP);
INSERT INTO "SupportArticle"("id","question","answer","category","audience","isStarter","aliases","status","sortOrder","updatedAt") VALUES ('36aa8e0a-448e-4aac-9d33-000000000005','¿Cómo habilito una sucursal adicional?','La sucursal principal queda habilitada al registrarte. Las sucursales adicionales las crea y habilita el superadmin. Solicita la gestión por este chat y elige Hablar con soporte para que el administrador revise tu caso.','Mi cuenta','ACCOUNT',true,'["nueva sucursal","habilitar sucursal"]','PUBLISHED',4,CURRENT_TIMESTAMP);
INSERT INTO "SupportArticle"("id","question","answer","category","audience","isStarter","aliases","status","sortOrder","updatedAt") VALUES ('36aa8e0a-448e-4aac-9d33-000000000006','¿Cómo reviso mi conexión con Lioren?','En Configuración, revisa la conexión con Lioren y los datos de la empresa asociada al token. Las métricas y folios disponibles provienen de Lioren. Si los datos de la empresa no coinciden o una emisión no está confirmada, pide revisión por soporte antes de intentar emitir nuevamente. No compartas el token por el chat.','Documentos electrónicos','ACCOUNT',false,'["lioren","folios disponibles"]','PUBLISHED',5,CURRENT_TIMESTAMP);
INSERT INTO "SupportArticle"("id","question","answer","category","audience","isStarter","aliases","status","sortOrder","updatedAt") VALUES ('36aa8e0a-448e-4aac-9d33-000000000007','¿Cómo solicito una nota de crédito?','En Ventas, busca la venta y usa la acción Nota de crédito. Revisa la validación y la confirmación de anulación total antes de continuar. La venta se anula y el inventario se repone tras la aceptación del SII. La devolución del dinero se gestiona por separado. Si faltan folios o el documento no está verificado, solicita revisión de soporte.','Documentos electrónicos','ACCOUNT',false,'["nota de credito","anular venta"]','PUBLISHED',6,CURRENT_TIMESTAMP);
INSERT INTO "SupportArticle"("id","question","answer","category","audience","isStarter","aliases","status","sortOrder","updatedAt") VALUES ('36aa8e0a-448e-4aac-9d33-000000000008','¿Qué es NexoPOS?','NexoPOS es un sistema para gestionar el punto de venta y la operación de tu negocio, con productos, inventario, ventas y sucursales. Puedes describir qué necesitas y solicitar hablar con una persona para recibir orientación.','Información general','PUBLIC',true,'["que es nexopos"]','PUBLISHED',7,CURRENT_TIMESTAMP);
INSERT INTO "SupportArticle"("id","question","answer","category","audience","isStarter","aliases","status","sortOrder","updatedAt") VALUES ('36aa8e0a-448e-4aac-9d33-000000000009','Ya soy cliente, ¿cómo recibo soporte?','Inicia sesión en tu cuenta de NexoPOS y abre el chat de soporte de tu panel. Así podremos identificar tu usuario y empresa para atender tu consulta. También puedes solicitar hablar con una persona desde este chat.','Soporte','PUBLIC',true,'["soy cliente","necesito soporte"]','PUBLISHED',8,CURRENT_TIMESTAMP);

CREATE INDEX "ChatSession_visitorId_updatedAt_idx" ON "ChatSession"("visitorId","updatedAt");
CREATE INDEX "ChatSession_mode_pendingSince_idx" ON "ChatSession"("mode","pendingSince");
CREATE INDEX "ChatSession_updatedAt_idx" ON "ChatSession"("updatedAt");

COMMIT;
